\label{ex: M-proto cats}
\begin{itemize}
	\item[1.]                                                                                                                                                                                              
When $\ensuremath{\mathscr{M}}$ is the class $\ensuremath{\mathscr{M}\mathsf{or}}$ of all morphisms or the class $\ensuremath{\mathscr{M}\mathsf{ono}}$ of all monomorphisms in $\ensuremath{\mathsf{C}}$, $\ensuremath{\mathsf{C}}$ satisfies the $\ensuremath{\mathscr{M}}$-version of protomodularity exactly when $\ensuremath{\mathsf{C}}$ is protomodular \cite{NEKEAC}.
	\item[2.] When $\ensuremath{\mathscr{M}}$ is the class $\ensuremath{\mathscr{SM}\mathsf{ono}}$ of all strong monomorphisms in $\ensuremath{\mathsf{C}}$, an $\ensuremath{\mathscr{M}}$-protomodular category is known as a \emph{weakly protomodular category}~\cite{CM-FM}.
\end{itemize}
	\item[3.] For examples concerning other classes $\ensuremath{\mathscr{M}}$ see Sections~\ref{sec: Exs} and~\ref{sec: Spl-proto}.

\label{thm: characterization of protomodularity}
Let $\ensuremath{\mathsf{C}}$ be a finitely complete category. The following conditions are equivalent:
\begin{itemize}
	\item[(i)] $\ensuremath{\mathsf{C}}$ is protomodular, i.e. the change-of-base functors $h^* \colon \ensuremath{\mathrm{Pt}}_Y(\ensuremath{\mathsf{C}}) \to \ensuremath{\mathrm{Pt}}_Z(\ensuremath{\mathsf{C}})$ are conservative for every $h \colon Z \to Y$;
	\item[(ii)] if $\ensuremath{\mathsf{C}}$ is also pointed, the \emph{Split Short Five Lemma} holds: given a commutative diagram of split short exact sequences
	\begin{equation}\label{diag:iv}
	\vcenter{\xymatrix@=25pt{ K' \ar@{|>->}[r]^-{\ker(f')} \ar[d]|-{\cong} & X' \ar@<2pt>[r]^-{f'} \ar[d]_-m & Y' \ar@<2pt>[l]^-{s'} \ar[d]|-{\cong} \\
		K \ar@{|>->}[r]_-{\ker(f)} & X \ar@<2pt>[r]^-f & Y, \ar@<2pt>[l]^-s}
	}
	\end{equation}
	it follows that $m$ is also an isomorphism;
	\item[(iii)] for any pullback of a point $(f,s)$ along an arbitrary morphism
	\begin{equation}\label{diag:iii}
	\vcenter{\xymatrix@=25pt{ Z\times_Y X \ar@<-2pt>[d]_-{\pi_Z} \ar[r]^-{\pi_X}  
 \ar@{-}[]+R+<6pt,-1pt>;[]+RD+<6pt,-6pt> 
 \ar@{-}[]+D+<.5ex,-6pt>;[]+RD+<6pt,-6pt> & X \ar@<-2pt>[d]_-f  \\
							   Z \ar@<-2pt>[u]_-{i_Z} \ar[r]_-h & Y, \ar@<-2pt>[u]_-s }}
	\end{equation}
	the pair $(\pi_X,s)$ is jointly extremally epimorphic;
		\item[(iv)] for any commutative diagram involving points $(f,s)$ and $(g,t)$
	\begin{equation}\label{diag:ii}
	\vcenter{
	\xymatrix@R=25pt@C=35pt{ U \ar@<-2pt>[d]_-{g} \ar[r]^-{u} \ar@{}[dr]|-{\framebox{\scriptsize\ensuremath{\mathrm{\mathrm{A}}}}} & X \ar@<-2pt>[d]_-{f} \ar[r]^-{x} \ar@{}[dr]|-{\framebox{\scriptsize\ensuremath{\mathrm{\mathrm{B}}}}} & A 		\ar[d]^-q \\
	V \ar@<-2pt>[u]_-{t} \ar[r]_-v & Y \ar@<-2pt>[u]_-{s} \ar[r]_-y & B}}
	\end{equation}
	(also commuting with the upward sections) where \framebox{\scriptsize\ensuremath{\mathrm{A}}} and \framebox{\scriptsize\ensuremath{\mathrm{A}}}\framebox{\scriptsize\ensuremath{\mathrm{B}}} are pullbacks, then \framebox{\scriptsize\ensuremath{\mathrm{B}}} is also a pullback.
\end{itemize}

\label{prop: M-proto iff SS5L for M} Let $\ensuremath{\mathsf{C}}$ be a pointed finitely complete category and $\ensuremath{\mathscr{M}}$ any class of morphisms of $\ensuremath{\mathsf{C}}$. The following conditions are equivalent:
\begin{itemize}
	\item[(i)] $\ensuremath{\mathsf{C}}$ is $\ensuremath{\mathscr{M}}$-protomodular;
	\item[(ii)] the Split Short Five Lemma holds with respect to $\ensuremath{\mathscr{M}}$.
\end{itemize}

\label{prop: M-proto iff orthogonal to M} Let $\ensuremath{\mathsf{C}}$ be a finitely complete category and $\ensuremath{\mathscr{M}}$ a class of monomorphisms of $\ensuremath{\mathsf{C}}$. The following conditions are equivalent:
\begin{itemize}
	\item[(i)] $\ensuremath{\mathsf{C}}$ is $\ensuremath{\mathscr{M}}$-protomodular;
	\item[(ii)] for any pullback of a point $(f,s)$ along an arbitrary morphism as in \eqref{diag:iii},	the pair $(\pi_X,s)$ is orthogonal to the class $\ensuremath{\mathscr{M}}$.
\end{itemize}

\label{prop: pb pp} Let $\ensuremath{\mathsf{C}}$ be a finitely complete category and $\ensuremath{\mathscr{M}}$ a class of morphisms of $\ensuremath{\mathsf{C}}$ which is left-cancellative, that is, $ba\in \ensuremath{\mathscr{M}} \Rightarrow a\in \ensuremath{\mathscr{M}}$. The following conditions are equivalent:
\begin{itemize}
	\item[(i)] $\ensuremath{\mathsf{C}}$ is $\ensuremath{\mathscr{M}}$-protomodular;
	\item[(ii)] for any commutative diagram involving points $(f,s)$ and $(g,t)$
	\[\xymatrix@R=25pt@C=35pt{ U \ar@<-2pt>[d]_-{g} \ar[r]^-{u} \ar@{}[dr]|-{\framebox{\scriptsize\ensuremath{\mathrm{\mathrm{A}}}}} & X \ar@<-2pt>[d]_-{f} \ar[r]^-{m\in \ensuremath{\mathscr{M}}} \ar@{}[dr]|-{\framebox{\scriptsize\ensuremath{\mathrm{\mathrm{B}}}}} & A 		\ar[d]^-q \\
	V \ar@<-2pt>[u]_-{t} \ar[r]_-v & Y \ar@<-2pt>[u]_-{s} \ar[r]_-y & B}
	\]
	(also commuting with the upward sections) where \framebox{\scriptsize\ensuremath{\mathrm{A}}} and \framebox{\scriptsize\ensuremath{\mathrm{A}}}\framebox{\scriptsize\ensuremath{\mathrm{B}}} are pullbacks, then \framebox{\scriptsize\ensuremath{\mathrm{B}}} is also a pullback.
\end{itemize}

\label{prop: pb pp for regular cat} Let $\ensuremath{\mathsf{C}}$ be a regular category and $\ensuremath{\mathscr{M}}$ a class of morphisms of $\ensuremath{\mathsf{C}}$ with the properties
\begin{itemize}
	\item[(P1)] $\ensuremath{\mathscr{M}}$ is left-cancellative;
	\item[(P2)] $\ensuremath{\mathscr{M}}$ is closed under composition;
	\item[(P3)] $m\in \ensuremath{\mathscr{M}} \Rightarrow m\times m \in \ensuremath{\mathscr{M}}$;
	\item[(P4)] for any pullback projections $\pi_Z$, $\pi_X$, the monomorphism $\langle \pi_Z,\pi_X\rangle\colon Z\times_Y X\rightarrowtail Z\times X$ is in $\ensuremath{\mathscr{M}}$.
\end{itemize}
The following conditions are equivalent:
\begin{itemize}
	\item[(i)] $\ensuremath{\mathsf{C}}$ is $\ensuremath{\mathscr{M}}$-protomodular;
	\item[(ii)] for any commutative diagram
	\[\xymatrix@R=25pt@C=35pt{ U \ar@{>>}[d]_-{g} \ar[r]^-{u} \ar@{}[dr]|-{\framebox{\scriptsize\ensuremath{\mathrm{\mathrm{A}}}}} & X \ar@{>>}[d]_-{f} \ar[r]^-{m\in \ensuremath{\mathscr{M}}} \ar@{}[dr]|-{\framebox{\scriptsize\ensuremath{\mathrm{\mathrm{B}}}}} & A 		\ar[d]^-q \\
	V \ar[r]_-v & Y \ar[r]_-y & B}
	\]
	where $f,g$ are regular epimorphisms, if \framebox{\scriptsize\ensuremath{\mathrm{A}}} and \framebox{\scriptsize\ensuremath{\mathrm{A}}}\framebox{\scriptsize\ensuremath{\mathrm{B}}} are pullbacks, then \framebox{\scriptsize\ensuremath{\mathrm{B}}} is also a pullback.
\end{itemize}

\label{prop: regular M-proto iff S5L for M} Let $\ensuremath{\mathsf{C}}$ be a pointed regular category and $\ensuremath{\mathscr{M}}$ a class of morphisms of $\ensuremath{\mathsf{C}}$ with the properties
\begin{itemize}
	\item[(P1)] $\ensuremath{\mathscr{M}}$ is left-cancellative;
	\item[(P2)] $\ensuremath{\mathscr{M}}$ is closed under composition;
	\item[(P3)] $m\in \ensuremath{\mathscr{M}} \Rightarrow m\times m \in \ensuremath{\mathscr{M}}$;
	\item[(P4)] for any pullback projections $\pi_Z$, $\pi_X$, the monomorphism $\langle \pi_Z,\pi_X\rangle\colon Z\times_Y X\rightarrowtail Z\times X$ is in $\ensuremath{\mathscr{M}}$.
\end{itemize} The following conditions are equivalent:
\begin{itemize}
	\item[(i)] $\ensuremath{\mathsf{C}}$ is $\ensuremath{\mathscr{M}}$-protomodular;
	\item[(ii)] the Short Five Lemma holds with respect to $\ensuremath{\mathscr{M}}$, i.e. given a commutative diagram of short exact sequences,
	\[\xymatrix@=25pt{ K \ar@{|>->}[r]^-{\ker(f')} \ar@{=}[d] & X' \ar@{|>}[r]^-{f'} \ar[d]^-{m\in \ensuremath{\mathscr{M}}} & Y \ar@{=}[d] \\
		K \ar@{|>->}[r]_-{\ker(f)} & X \ar@{|>}[r]_-f & Y,}\]
		$m$ is necessarily an isomorphism.
\end{itemize}

\label{cor:top}
Let $F\colon \ensuremath{\mathsf{C}}\to \ensuremath{\mathsf{D}}$ be a topological functor between finitely complete categories, and $\ensuremath{\mathscr{M}}$ a class of $F$-initial morphisms of $\ensuremath{\mathsf{C}}$. Then $\ensuremath{\mathsf{C}}$ is $\ensuremath{\mathscr{M}}$-protomodular provided that $\ensuremath{\mathsf{D}}$ is $F(\ensuremath{\mathscr{M}})$-protomodular.

In particular, if $\ensuremath{\mathsf{D}}$ is protomodular, then $\ensuremath{\mathsf{C}}$ is $\ensuremath{\mathscr{SM}\mathsf{ono}}$-protomodular.

\label{exe:Grp}
Analogously:
\begin{itemize}
\item $\ensuremath{\mathsf{Grp}}$ is a (co)complete protomodular category;
\item as shown in \cite{CM-FM, CM1, CM2} respectively, the forgetful functors $\ensuremath{\mathsf{OrdGrp}}\to\ensuremath{\mathsf{Grp}}$, $\ensuremath{\mathsf{ROrdGrp}}\to\ensuremath{\mathsf{Grp}}$, $V$-$\ensuremath{\mathsf{Grp}}\to\ensuremath{\mathsf{Grp}}$ are topological, where $\ensuremath{\mathsf{ROrdGrp}}$ denotes the category of right-ordered groups and monotone group homomorphisms, and $V\mbox{-}\ensuremath{\mathsf{Grp}}$ has as objects $V$-groups and as morphisms $V$-functors which are group homomorphisms, for a suitable quantale $V$ (as introduced in \cite{CM1}).
\end{itemize}
Hence, using again Corollary \ref{cor:top}, we conclude that the following categories are $\ensuremath{\mathscr{SM}\mathsf{ono}}$-pro\-to\-mo\-du\-lar:
\[\ensuremath{\mathsf{OrdGrp}},\;\ensuremath{\mathsf{ROrdGrp}},\;V\mbox{-}\ensuremath{\mathsf{Grp}}.\]
None of these categories is protomodular, as shown in \cite{CM-FM, CM1, CM2} respectively.

\label{lem: h* reflects monos iff pbs reflect monos} In a finitely complete category $\ensuremath{\mathsf{C}}$, the following conditions are equivalent:
\begin{itemize}
	\item[(i)] any $h^*$ reflects monomorphisms;
	\item[(ii)] pullbacks in $\ensuremath{\mathsf{C}}$ reflect monomorphisms.
\end{itemize}

\label{lem: M-proto for Nil_c} Let $\ensuremath{\mathsf{C}}$ be a semi-abelian category and $\ensuremath{\mathscr{M}}$ a class of monomorphisms in $\ensuremath{\mathsf{C}}^\op$ such that all morphisms in $\ensuremath{\mathscr{M}}^\op$ are cokernels. Then $\ensuremath{\mathsf{C}}^\op$ is $\ensuremath{\mathscr{M}}$-protomodular if and only if, for any pushout of type~\eqref{diag: po of split mono} and cokernel $e\in \ensuremath{\mathscr{M}}^\op$, we have
\begin{equation}\label{diag: M-proto in C^op with kernels}
 \left(\, \ensuremath{\mathrm{Ker}}(e) \subseteq \ensuremath{\mathrm{Ker}}(\beta)\cap \ensuremath{\mathrm{Ker}}(u) \,\right) \;\;\Rightarrow\;\; \ensuremath{\mathrm{Ker}}(e)=0.
\end{equation}

\label{def of difunctional}
A relation $X\stackrel{d_1}{\longleftarrow} D \stackrel{d_2}{\longrightarrow} Y$ in $\ensuremath{\mathsf{C}}$ is called \emph{difunctional} when the relation
\begin{equation}\label{W-difunctional}
  \xymatrix@C=40pt{\ensuremath{\mathsf{C}}(W,X) & \ar[l]_-{\ensuremath{\mathsf{C}}(W,d_1)} \ensuremath{\mathsf{C}}(W,D) \ar[r]^-{\ensuremath{\mathsf{C}}(W,d_2)} & \ensuremath{\mathsf{C}}(W,Y)}
\end{equation}
in $\ensuremath{\mathsf{Set}}$ is difunctional~\cite{Riguet}, for every object $W$ of $\ensuremath{\mathsf{C}}$. More precisely, given morphisms $x,u\colon W\to X$, $y,v\colon W\to Y$, we have $(xD y \wedge uDy \wedge uDv)\Rightarrow xDv$, that is
\begin{equation}\label{eq: difunctional with relations}
\vcenter{
\hbox{\resizebox{0.9\textwidth}{!}{$
\begin{array}{llll}
	\xymatrix@C=10pt@R=10pt{& X \\ W \ar[ur]^-x \ar[dr]_-y \ar@{.>}[rr]|-{\langle x,y \rangle} & & D, \ar[ul]_-{d_1} \ar[dl]^-{d_2} \\ & Y} &
	\xymatrix@C=10pt@R=10pt{& X \\ W \ar[ur]^-u \ar[dr]_-y \ar@{.>}[rr]|-{\langle u,y \rangle} & & D, \ar[ul]_-{d_1} \ar[dl]^-{d_2} \\ & Y} &
	\xymatrix@C=10pt@R=10pt{& X \\ W \ar[ur]^-u \ar[dr]_-v \ar@{.>}[rr]|-{\langle u,v \rangle} & & D\;\;\Rightarrow \ar[ul]_-{d_1} \ar[dl]^-{d_2} \\ & Y}&
	\xymatrix@C=10pt@R=10pt{& X \\ W \ar[ur]^-x \ar[dr]_-v \ar@{.>}[rr]|-{\langle x,v \rangle} & & D. \ar[ul]_-{d_1} \ar[dl]^-{d_2} \\ & Y}
\end{array}$}}}
\end{equation}

\label{ex: M-Mal'tsev cats}
\begin{itemize}
	\item[1.] When $\ensuremath{\mathscr{M}}=\ensuremath{\mathscr{M}\mathsf{ono}}$, an $\ensuremath{\mathscr{M}}$-Mal'tsev category is just an ``ordinary'' Mal'tsev category.
	\item[2.] When $\ensuremath{\mathscr{M}}=\ensuremath{\mathscr{SM}\mathsf{ono}}$, an $\ensuremath{\mathscr{M}}$-Mal'tsev category is a weakly Mal'tsev category~\cite{JMF} (see definition in Remark~\ref{rem: proto => Mal'tsev}).
\end{itemize}

\label{prop: M-proto => Pt_Y(CC) is unital} Let $\ensuremath{\mathsf{C}}$ be an $\ensuremath{\mathscr{M}}$-protomodular category, where $\ensuremath{\mathscr{M}}$ is a class of monomorphisms of $\ensuremath{\mathsf{C}}$. Given an arbitrary pullback of points
	\begin{equation}\label{diag:pb of points}
	\vcenter{\xymatrix@=25pt{ Z\times_Y X \ar@<-2pt>[d]_-{\pi_Z} \ar@<2pt>[r]^-{\pi_X}                               
 \ar@{-}[]+R+<4pt,-3pt>;[]+RD+<4pt,-6pt> 
 \ar@{-}[]+D+<3pt,-6pt>;[]+RD+<4pt,-6pt> & X \ar@<-2pt>[d]_-f \ar@<2pt>[l]^-{i_X} \\
							   Z \ar@<-2pt>[u]_-{i_Z} \ar@<2pt>[r]^-h & Y, \ar@<-2pt>[u]_-s \ar@<2pt>[l]^-t}}
	\end{equation}
the pair $(i_Z,i_X)$ is orthogonal to the class $\ensuremath{\mathscr{M}}$.

\label{prop: Pt_Y(CC) unital <=> M-Mal'tsev} Let $\ensuremath{\mathsf{C}}$ be a category with pullbacks and $\ensuremath{\mathscr{M}}$ a class of monomorphisms of $\ensuremath{\mathsf{C}}$ with the properties
\begin{itemize}
	\item[(P2)] $\ensuremath{\mathscr{M}}$ is closed under composition;
	\item[(P4)] for any pullback projections $\pi_Z$, $\pi_X$, the monomorphism $\langle \pi_Z,\pi_X\rangle\colon Z\times_Y X\rightarrowtail Z\times X$ is in $\ensuremath{\mathscr{M}}$;
	\item[(P5)] $\ensuremath{\mathscr{M}}$ is stable under pullbacks.
\end{itemize}
The following conditions are equivalent:
\begin{itemize}
	\item[(i)] $\ensuremath{\mathsf{C}}$ satisfies the property of Proposition~\ref{prop: M-proto => Pt_Y(CC) is unital};
	\item[(ii)] any relation $\langle d_1,d_2\rangle\colon  D \rightarrowtail X\times Y$ in $\ensuremath{\mathscr{M}}$ is difunctional.
\end{itemize}

\label{prop: protovsMaltsev} Let $\ensuremath{\mathsf{C}}$ be a category with pullbacks and $\ensuremath{\mathscr{M}}$ a class of monomorphisms of $\ensuremath{\mathsf{C}}$ with the properties
\begin{itemize}
	\item[(P2)] $\ensuremath{\mathscr{M}}$ is closed under composition;
	\item[(P4)] for any pullback projections $\pi_Z$, $\pi_X$, the monomorphism $\langle \pi_Z,\pi_X\rangle\colon Z\times_Y X\rightarrowtail Z\times X$ is in $\ensuremath{\mathscr{M}}$;
	\item[(P5)] $\ensuremath{\mathscr{M}}$ is stable under pullbacks.
\end{itemize}If $\ensuremath{\mathsf{C}}$ is an $\ensuremath{\mathscr{M}}$-protomodular category then it is an $\ensuremath{\mathscr{M}}$-Mal'tsev category.

\label{rem: proto => Mal'tsev}
\begin{itemize}
	\item[1.] When $\ensuremath{\mathscr{M}}=\ensuremath{\mathscr{M}\mathsf{or}}$ or $\ensuremath{\mathscr{M}}=\ensuremath{\mathscr{M}\mathsf{ono}}$, Proposition~\ref{prop: M-proto => Pt_Y(CC) is unital} translates to: any protomodular category is a Mal'tsev category. Indeed, any pullback of points~\eqref{diag:pb of points} being such that $(i_Z,i_X)$ is jointly extremally epimorphic is equivalent to every $\ensuremath{\mathrm{Pt}}_Y(\ensuremath{\mathsf{C}})$ being a unital category~\cite{MCFPO}, for any object $Y$ of $\ensuremath{\mathsf{C}}$. This latter is a well-known characterisation of Mal'tsev categories~\cite[Proposition 10]{MCFPO}. Proposition~\ref{prop: Pt_Y(CC) unital <=> M-Mal'tsev} recovers the equivalence between two well-known characterisations of Mal'tsev categories: every $\ensuremath{\mathrm{Pt}}_Y(\ensuremath{\mathsf{C}})$ is a unital category, for any object $Y$ of $\ensuremath{\mathsf{C}}$, and every relation $D\colon X{\rightarrow\hspace*{-2.4ex}{\mapstochar}\hspace*{2.2ex}} Y$ is difunctional.
	\item[2.] When $\ensuremath{\mathscr{M}}=\ensuremath{\mathscr{SM}\mathsf{ono}}$, Proposition~\ref{prop: M-proto => Pt_Y(CC) is unital} translates to: any weakly protomodular category is a weakly Mal'tsev category. Recall  from~\cite{NMFweakly} that a \emph{weakly Mal'tsev category} is defined by the property that any pullback of points~\eqref{diag:pb of points} is such that $(i_Z,i_X)$ is jointly epimorphic. Proposition~\ref{prop: Pt_Y(CC) unital <=> M-Mal'tsev} recovers the characterisation of weakly Mal'tsev categories as the finitely complete categories such that every strong relation $D\colon X{\rightarrow\hspace*{-2.4ex}{\mapstochar}\hspace*{2.2ex}} Y$ is difunctional (see~\cite{JMF}).
\end{itemize}

\label{pps for ff-ms}
Let $a\colon A\to B$ and $b\colon B\to C$ be morphisms in an $\ensuremath{\mathsf{Ord}}$-category $\ensuremath{\mathbb{C}}$. Then:
\begin{itemize}
	\item[(F1)] if $ba$ is an ff-monomorphism, then $a$ is an ff-monomorphism;
	\item[(F2)] if $a$ and $b$ are ff-monomorphisms, then $ba$ is also an ff-monomorphism;
	\item[(F3)] if $a$ is an ff-monomorphism, then $a\times a$ is an ff-monomorphism;
	\item[(F4)] for any 2-pullback projections $\pi_Z$, $\pi_X$, the morphism $\langle \pi_Z,\pi_X\rangle\colon Z\times_Y X\rightarrowtail Z\times X$ is an ff-monomorphism;
	\item[(F5)] ff-monomorphisms are stable under 2-pullbacks.\hfill $\Box$
\end{itemize}

{\bf $\ensuremath{\mathsf{Ord}}$-enrichments of $\ensuremath{\mathsf{OrdGrp}}$.}
We start by recalling two different $\ensuremath{\mathsf{Ord}}$-enrichment of $\ensuremath{\mathsf{OrdGrp}}$ studied in \cite{CMR}. We denote by $\ensuremath{\mathbb{O}}\ensuremath{\mathsf{rdGrp}}$ the one given, for any morphisms $f,g\colon X\to Y$, by $f\le g$ if, for all $x\in X$, $f(x)\le g(x)$, while we denote by $\ensuremath{\mathbb{O}}\ensuremath{\mathsf{rdGrp}}_+$ the other enrichment, where $f\le g$ if $f(x)\le g(x)$ for all positive elements $x$ of $X$. We point out that the former enrichment induces an equivalence relation on the morphisms.

As shown in \cite{CM-FM} and in Example \ref{exe:Grp} respectively, $\ensuremath{\mathsf{OrdGrp}}$ is not a protomodular category but it is $\ensuremath{\mathscr{SM}\mathsf{ono}}$-protomodular. Here we show that neither $\ensuremath{\mathbb{O}}\ensuremath{\mathsf{rdGrp}}$ nor $\ensuremath{\mathbb{O}}\ensuremath{\mathsf{rdGrp}}_+$ are $\ensuremath{\mathsf{Ord}}$-protomodular. The failure of this property is due to the fact that, for both $\ensuremath{\mathsf{Ord}}$-enrichments, ff-monomorphisms do not characterise ``initial monomorphisms", that is, injective homomorphisms whose domain has the initial topology. Indeed:
\begin{itemize}
\item a monomorphism $m\colon X'\to X$ is an ff-monomorphism in $\ensuremath{\mathbb{O}}\ensuremath{\mathsf{rdGrp}}$ if and only if, for all $x,x'\in X'$, $x\cong x'$ whenever $m(x)\cong m(x')$, so, in particular, if the order on $X'$ is anti-symmetric $m$ is an ff-monomorphism if and only if it is monomorphic;
\item a monomorphism $m\colon X'\to X$ is an ff-monomorphism in $\ensuremath{\mathbb{O}}\ensuremath{\mathsf{rdGrp}}_+$ if and only if, for all $x,x'\in X'$, if $0\le x$ and $0\le x'$, then $x\leq x'$ whenever $m(x)\le m(x')$. Hence if the only positive element of $X'$ is $0$, $m$ is an ff-monomorphism if and only if it is monomorphic.
\end{itemize}
Diagrams \eqref{diag:grp} and \eqref{diag:grpp} show, respectively, that $\ensuremath{\mathbb{O}}\ensuremath{\mathsf{rdGrp}}$ and $\ensuremath{\mathbb{O}}\ensuremath{\mathsf{rdGrp}}_+$ fail to satisfy the ff-monomorphism version of protomodularity.
\begin{equation}\label{diag:grp}
\vcenter{\xymatrix@=25pt{ (\ensuremath{\mathbb{Z}},\ensuremath{\mathbb{N}}) \ar@{ >->}[r]^-{\langle 1_{\ensuremath{\mathbb{Z}}},0\rangle} \ar@{=}[d] &  (\ensuremath{\mathbb{Z}}\times \ensuremath{\mathbb{Z}}, P_\prod) \ar@<2pt>[r]^-{\pi_2} \ar[d]_-{1_{\ensuremath{\mathbb{Z}}\times \ensuremath{\mathbb{Z}}}} & (\ensuremath{\mathbb{Z}},\ensuremath{\mathbb{N}}) \ar@<2pt>[l]^-{\langle 0, 1_{\ensuremath{\mathbb{Z}}}\rangle} \ar@{=}[d] \\
		(\ensuremath{\mathbb{Z}},\ensuremath{\mathbb{N}}) \ar@{ >->}[r]_-{\langle 1_{\ensuremath{\mathbb{Z}}},0\rangle} & (\ensuremath{\mathbb{Z}}\times \ensuremath{\mathbb{Z}}, P_\lex) \ar@<2pt>[r]^-{\pi_2} & (\ensuremath{\mathbb{Z}},\ensuremath{\mathbb{N}}), \ar@<2pt>[l]^-{\langle 0, 1_{\ensuremath{\mathbb{Z}}}\rangle}}}
\end{equation}
\begin{equation}\label{diag:grpp}
\vcenter{\xymatrix@=25pt{ (\ensuremath{\mathbb{Z}},\{0\}) \ar@{ >->}[r]^-{\langle 1_{\ensuremath{\mathbb{Z}}},0\rangle} \ar@{=}[d] &  (\ensuremath{\mathbb{Z}}\times \ensuremath{\mathbb{Z}}, P_\prod) \ar@<2pt>[r]^-{\pi_2} \ar[d]_-{1_{\ensuremath{\mathbb{Z}}\times \ensuremath{\mathbb{Z}}}} & (\ensuremath{\mathbb{Z}},\ensuremath{\mathbb{N}}) \ar@<2pt>[l]^-{\langle 0, 1_{\ensuremath{\mathbb{Z}}}\rangle} \ar@{=}[d] \\
		(\ensuremath{\mathbb{Z}},\{0\}) \ar@{ >->}[r]_-{\langle 1_{\ensuremath{\mathbb{Z}}},0\rangle} & (\ensuremath{\mathbb{Z}}\times \ensuremath{\mathbb{Z}}, P_\lex) \ar@<2pt>[r]^-{\pi_2} & (\ensuremath{\mathbb{Z}},\ensuremath{\mathbb{N}}), \ar@<2pt>[l]^-{\langle 0, 1_{\ensuremath{\mathbb{Z}}}\rangle}}}
\end{equation}
In both diagrams the order of $\mathbb{Z}\times\mathbb{Z}$ in the top row is the product order, while in the bottom row is the lexicographic order (see \cite{CM-FM} for details); that is, in \eqref{diag:grp} the positive cones are given by $P_\prod=\mathbb{N}\times\mathbb{N}$ and $P_\lex=\{(n,m)\in \mathbb{Z}\times\mathbb{Z}\,;\,m>0\}\,\cup\,\{(n,0)\,;\,n\in\mathbb{N}\}=\mathbb{Z}\times\mathbb{N}_1\,\cup\,\mathbb{N}\times\{0\}$, while in \eqref{diag:grpp} $P_\prod=\{0\}\times\mathbb{N}$ and $P_\lex=\mathbb{Z}\times\mathbb{N}_1\,\cup\,\{(0,0)\}$. In both cases $P_\prod \subset P_\lex$ and so the identity $1_{\mathbb{Z}\times\mathbb{Z}}$ is a monotone bijection but not an isomorphism.

\begin{enumerate}
\item[1.] As shown in \cite{CR}, $\ensuremath{\mathbb{O}}\ensuremath{\mathsf{rdGrp}}_+$ is $\ensuremath{\mathsf{Ord}}$-Mal'tsev, hence this is an example of an $\ensuremath{\mathsf{Ord}}$-Mal'tsev category which is not $\ensuremath{\mathsf{Ord}}$-protomodular.

\item[2.] We do not have an example of an $\ensuremath{\mathsf{Ord}}$-protomodular category which is not protomodular.

\item[3.] We point out that the notion of $\ensuremath{\mathsf{Ord}}$-protomodular is not directly related to the notion of lax protomodularity introduced in \cite{CMR}: lax protomodularity deals with the properties of the lax comma change-of-base functor.
\end{enumerate}
